import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import '../index.css'; // <- global styles
import { signInWithGoogle } from '../firebaseConfig'; // <-- import the Google function

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const navigate = useNavigate();

  function handleSubmit(e) {
    e.preventDefault();
    setError('');
    const usersJson = localStorage.getItem('users');
    const users = usersJson ? JSON.parse(usersJson) : [];
    const found = users.find(u => u.email === email && u.password === password);
    if (!found) {
      setError('Invalid email or password. Or sign up first.');
      return;
    }

    const token = btoa(email + ':' + Date.now());
    localStorage.setItem('authToken', token);
    localStorage.setItem('currentUser', JSON.stringify({ email }));

    alert("Login successful!");

    // If profile already created, go straight to dashboard. Otherwise role-selection.
    const alreadyCreated = localStorage.getItem('profileCreated');
    if (alreadyCreated === 'true') {
      navigate('/dashboard');
    } else {
      navigate('/role-selection');
    }
  }

  async function handleGoogleLogin() {
    try {
      const user = await signInWithGoogle();
      if (user) {
        navigate('/role-selection');
      }
    } catch (err) {
      console.error(err);
      alert('Google Sign-in failed.');
    }
  }

  return (
    <div className="auth-page">
      <div className="auth-container">
        <h1>SoftScale</h1>
        <form onSubmit={handleSubmit}>
          <input
            type="email"
            placeholder="Email address"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />

          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />

          {error && <div style={{color:'#cc3b3b', marginTop:8}}>{error}</div>}

          <button type="submit">Login</button>
        </form>

        <div className="divider">or</div>

        <button
          type="button"
          onClick={handleGoogleLogin}
          className="google-btn"
        >
          <img
            src="https://www.gstatic.com/firebasejs/ui/2.0.0/images/auth/google.svg"
            alt="Google logo"
            style={{ width: '20px', marginRight: '8px' }}
          />
          Continue with Google
        </button>

        <p>
          Don’t have an account? <Link to="/signup">Sign up</Link>
        </p>
      </div>
    </div>
  );
}
